diff --git a/src/main/java/org/jsoup/select/Collector.java b/src/main/java/org/jsoup/select/Collector.java
index de34eddf..13cf23d2 100644
--- a/src/main/java/org/jsoup/select/Collector.java
+++ b/src/main/java/org/jsoup/select/Collector.java
@@ -2,6 +2,10 @@ package org.jsoup.select;

 import org.jsoup.nodes.Element;
 import org.jsoup.nodes.Node;
+import org.jsoup.nodes.PseudoTextElement;
+import org.jsoup.nodes.TextNode;
+
+import java.util.ArrayList;

 import static org.jsoup.select.NodeFilter.FilterResult.CONTINUE;
 import static org.jsoup.select.NodeFilter.FilterResult.STOP;
@@ -24,10 +28,32 @@ public class Collector {
      */
     public static Elements collect (Evaluator eval, Element root) {
         Elements elements = new Elements();
-        NodeTraversor.traverse(new Accumulator(root, elements, eval), root);
+        // Check if we need to handle matchText pseudo-selector
+        if (containsMatchText(eval)) {
+            NodeTraversor.traverse(new MatchTextAccumulator(root, elements, eval), root);
+        } else {
+            NodeTraversor.traverse(new Accumulator(root, elements, eval), root);
+        }
         return elements;
     }

+    private static boolean containsMatchText(Evaluator eval) {
+        if (eval instanceof Evaluator.MatchText) {
+            return true;
+        }
+        if (eval instanceof CombiningEvaluator.And) {
+            for (Evaluator e : ((CombiningEvaluator.And) eval).evaluators) {
+                if (containsMatchText(e)) return true;
+            }
+        }
+        if (eval instanceof CombiningEvaluator.Or) {
+            for (Evaluator e : ((CombiningEvaluator.Or) eval).evaluators) {
+                if (containsMatchText(e)) return true;
+            }
+        }
+        return false;
+    }
+
     private static class Accumulator implements NodeVisitor {
         private final Element root;
         private final Elements elements;
@@ -86,4 +112,71 @@ public class Collector {
         }
     }

+    private static class MatchTextAccumulator implements NodeVisitor {
+        private final Element root;
+        private final Elements elements;
+        private final Evaluator eval;
+        private final Evaluator nonMatchTextEval;
+
+        MatchTextAccumulator(Element root, Elements elements, Evaluator eval) {
+            this.root = root;
+            this.elements = elements;
+            this.eval = eval;
+            this.nonMatchTextEval = removeMatchText(eval);
+        }
+
+        public void head(Node node, int depth) {
+            if (node instanceof Element) {
+                Element el = (Element) node;
+                // Check if element matches the non-MatchText part of the evaluator
+                if (nonMatchTextEval == null || nonMatchTextEval.matches(root, el)) {
+                    // Now find text nodes within this element and create pseudo-elements
+                    java.util.List<Node> children = new java.util.ArrayList<>(el.childNodes());
+                    for (int i = 0; i < children.size(); i++) {
+                        Node child = children.get(i);
+                        if (child instanceof TextNode) {
+                            TextNode textNode = (TextNode) child;
+                            String text = textNode.getWholeText().trim();
+                            if (text.length() > 0) {
+                                // Create pseudo-element
+                                PseudoTextElement pseudo = new PseudoTextElement(text, el.baseUri(), el, i);
+                                // Test the pseudo-element against the full evaluator
+                                if (eval.matches(root, pseudo)) {
+                                    elements.add(pseudo);
+                                }
+                            }
+                        }
+                    }
+                }
+            }
+        }
+
+        public void tail(Node node, int depth) {
+            // void
+        }
+    }
+
+    private static Evaluator removeMatchText(Evaluator eval) {
+        if (eval instanceof Evaluator.MatchText) {
+            return null;
+        }
+        if (eval instanceof CombiningEvaluator.And) {
+            CombiningEvaluator.And and = (CombiningEvaluator.And) eval;
+            ArrayList<Evaluator> remaining = new ArrayList<>();
+            for (Evaluator e : and.evaluators) {
+                if (!(e instanceof Evaluator.MatchText)) {
+                    remaining.add(e);
+                }
+            }
+            if (remaining.isEmpty()) {
+                return null;
+            } else if (remaining.size() == 1) {
+                return remaining.get(0);
+            } else {
+                return new CombiningEvaluator.And(remaining);
+            }
+        }
+        return eval;
+    }
+
 }
diff --git a/src/main/java/org/jsoup/select/Evaluator.java b/src/main/java/org/jsoup/select/Evaluator.java
index 87b1d481..b9dbabd3 100644
--- a/src/main/java/org/jsoup/select/Evaluator.java
+++ b/src/main/java/org/jsoup/select/Evaluator.java
@@ -396,10 +396,15 @@ public abstract class Evaluator {
     public static final class IsLastChild extends Evaluator {
 		@Override
 		public boolean matches(Element root, Element element) {
+			// Special handling for PseudoTextElement
+			if (element instanceof org.jsoup.nodes.PseudoTextElement) {
+				org.jsoup.nodes.PseudoTextElement pseudo = (org.jsoup.nodes.PseudoTextElement) element;
+				return pseudo.getParentEl() != null && pseudo.isLastChild();
+			}
 			final Element p = element.parent();
 			return p != null && !(p instanceof Document) && element.elementSiblingIndex() == p.children().size()-1;
 		}
-    	
+
 		@Override
 		public String toString() {
 			return ":last-child";
@@ -558,10 +563,16 @@ public abstract class Evaluator {
     public static final class IsFirstChild extends Evaluator {
     	@Override
     	public boolean matches(Element root, Element element) {
+    		// Special handling for PseudoTextElement
+    		if (element instanceof org.jsoup.nodes.PseudoTextElement) {
+    			org.jsoup.nodes.PseudoTextElement pseudo = (org.jsoup.nodes.PseudoTextElement) element;
+    			return pseudo.getParentEl() != null && pseudo.isFirstChild();
+    		}
     		final Element p = element.parent();
-    		return p != null && !(p instanceof Document) && element.elementSiblingIndex() == 0;
+    		if (p == null || p instanceof Document) return false;
+    		return element.elementSiblingIndex() == 0;
     	}
-    	
+
     	@Override
     	public String toString() {
     		return ":first-child";
@@ -751,6 +762,19 @@ public abstract class Evaluator {
         }
     }

+    /**
+     * Pseudo-class for matching text nodes as elements.
+     */
+    public static final class MatchText extends Evaluator {
+        @Override
+        public boolean matches(Element root, Element element) {
+            return element instanceof org.jsoup.nodes.PseudoTextElement;
+        }

+        @Override
+        public String toString() {
+            return ":matchText";
+        }
+    }

 }
